import 'package:flutter/material.dart';
import 'package:hyper_ui/core.dart';

class QAutoComplete extends StatefulWidget {
  const QAutoComplete({
    required this.label,
    required this.onChanged,
    super.key,
    this.items = const [],
    this.onFuture,
    this.validator,
    this.hint,
    this.helper,
    this.value,
    this.enabled = true,
  });
  final String label;
  final String? hint;
  final String? helper;
  final dynamic value;
  final List<Map<String, dynamic>> items;
  final String? Function(String? item)? validator;
  final Function(dynamic value, String? label) onChanged;
  final Function()? onFuture;
  final bool enabled;

  @override
  State<QAutoComplete> createState() => _QAutoCompleteState();
}

class _QAutoCompleteState extends State<QAutoComplete> {
  List<Map<String, dynamic>> items = [];

  @override
  void initState() {
    super.initState();

    if (widget.onFuture == null) {
      for (final item in widget.items) {
        items.add(Map.from(item));
      }
    } else {
      loadData();
    }
  }

  loadData() async {
    final List<Map<String, dynamic>> serviceItems = await widget.onFuture!();
    for (final item in serviceItems) {
      items.add(item);
    }
    setState(() {});
  }

  bool get hasValue {
    var val = widget.value;
    var index =
        items.indexWhere((i) => i["value"].toString() == val.toString());
    return index > -1;
  }

  String get getLabelFromCurrentValue {
    var val = widget.value;
    return items
        .firstWhere((i) => i["value"].toString() == val.toString())['label']
        .toString();
  }

  @override
  Widget build(BuildContext context) {
    if (items.isEmpty) return Container();

    return LayoutBuilder(
      builder: (context, constraints) {
        return Container(
          margin: const EdgeInsets.only(
            bottom: 12,
          ),
          child: FormField(
            initialValue: false,
            builder: (field) {
              return Autocomplete<Map>(
                initialValue: !hasValue || widget.value == null
                    ? null
                    : TextEditingValue(
                        text: getLabelFromCurrentValue,
                      ),
                fieldViewBuilder: (
                  context,
                  textEditingController,
                  focusNode,
                  onFieldSubmitted,
                ) {
                  return TextFormField(
                    controller: textEditingController,
                    focusNode: focusNode,
                    onFieldSubmitted: (text) => onFieldSubmitted(),
                    validator: widget.validator,
                    enabled: widget.enabled,
                    decoration: InputDecoration(
                      labelText: widget.label,
                      errorText: field.errorText,
                      suffixIcon: SizedBox(
                        width: 70.0,
                        child: Row(
                          mainAxisAlignment: MainAxisAlignment.end,
                          crossAxisAlignment: CrossAxisAlignment.center,
                          children: [
                            InkWell(
                              onTap: () {
                                textEditingController.clear();
                                widget.onChanged(null, null);
                              },
                              child: const Icon(Icons.close),
                            ),
                            const SizedBox(
                              width: 8.0,
                            ),
                            const Icon(Icons.search),
                            const SizedBox(
                              width: 8.0,
                            ),
                          ],
                        ),
                      ),
                      helperText: widget.helper,
                      hintText: widget.hint,
                    ),
                  );
                },
                onSelected: (Map map) {
                  final String? label = map['label']?.toString();
                  final dynamic value = map['value'];
                  widget.onChanged(value, label);
                },
                optionsBuilder: (TextEditingValue textEditingValue) {
                  if (textEditingValue.text == '') {
                    return const Iterable<Map>.empty();
                  }
                  return items.where((Map option) {
                    return option['label']
                        .toString()
                        .toLowerCase()
                        .contains(textEditingValue.text.toLowerCase());
                  });
                },
                displayStringForOption: (option) {
                  return option['label'].toString();
                },
                optionsViewBuilder: (context, onSelected, options) => Align(
                  alignment: Alignment.topLeft,
                  child: Material(
                    color: Colors.transparent,
                    child: ClipRRect(
                      clipBehavior: Clip.none,
                      borderRadius: const BorderRadius.vertical(
                        bottom: Radius.circular(12),
                      ),
                      child: Container(
                        width: constraints.biggest.width,
                        margin: const EdgeInsets.only(top: 10),
                        child: Wrap(
                          children: [
                            Container(
                              clipBehavior: Clip.antiAlias,
                              decoration: BoxDecoration(
                                color: Theme.of(Get.currentContext!)
                                    .scaffoldBackgroundColor,
                                borderRadius: const BorderRadius.all(
                                  Radius.circular(12),
                                ),
                                border: Border.all(
                                  color: primaryColor,
                                ),
                              ),
                              child: ListView.builder(
                                padding: EdgeInsets.zero,
                                itemCount: options.length,
                                shrinkWrap: true,
                                itemBuilder: (BuildContext context, int index) {
                                  final selected =
                                      AutocompleteHighlightedOption.of(
                                            context,
                                          ) ==
                                          index;
                                  final option = options.elementAt(index);

                                  return InkWell(
                                    focusColor: Colors.transparent,
                                    hoverColor: Colors.transparent,
                                    highlightColor: Colors.transparent,
                                    onTap: () => onSelected(option),
                                    child: Container(
                                      decoration: BoxDecoration(
                                        color: selected
                                            ? Theme.of(context).focusColor
                                            : null,
                                        borderRadius: BorderRadius.only(
                                          topLeft: Radius.circular(
                                            index == 0 ? 12 : 0,
                                          ),
                                          topRight: Radius.circular(
                                            index == 0 ? 12 : 0,
                                          ),
                                          bottomLeft: Radius.circular(
                                            index == options.length - 1
                                                ? 12
                                                : 0.0,
                                          ),
                                          bottomRight: Radius.circular(
                                            index == options.length - 1
                                                ? 12
                                                : 0.0,
                                          ),
                                        ),
                                      ),
                                      child: ListTile(
                                        leading: option['photo'] == null
                                            ? null
                                            : CircleAvatar(
                                                backgroundImage: NetworkImage(
                                                  option['photo'],
                                                ),
                                              ),
                                        title: Text("${option["label"]}"),
                                        subtitle: option['info'] == null
                                            ? null
                                            : Text("${option["info"]}"),
                                      ),
                                    ),
                                  );
                                },
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        );
      },
    );
  }
}

