                child: Stack(
                  children: [
                    if (loading)
                      Container(
                        decoration: BoxDecoration(
                          color: Colors.grey.withOpacity(0.6),
                        ),
                      ),
                    if (loading)
                      const Center(
                        child: CircularProgressIndicator(),
                      ),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

